    if (!validation.ok) {
      setCategoryError(validation.errors.join(". "));
      setCategoryMessage(null);
      return;
    }

    const duplicateCategory = categories.find(
      (c) => c.name.trim().toLowerCase() === categoryName.trim().toLowerCase()
    );
    if (duplicateCategory) {
      setCategoryError("A category with this name already exists.");
      setCategoryMessage(null);
      return;
    }

    if (!requireOrganization("add category")) {
      setCategoryError("Organization not loaded. Please login again.");
      setCategoryMessage(null);
      return;
    }

    setCategoryError(null);
    setCategoryMessage(null);
    setCategoriesLoading(true);

    const { data, error } = await supabase.from("categories").insert({
      name: categoryName.trim(),
      parent_category_id: parentCategoryId,
      overselling_policy:
        categoryOversellingPolicy === "allow" || categoryOversellingPolicy === "block"
          ? categoryOversellingPolicy
          : null,
      organization_id: currentOrganizationId,
    }).select("id").single();

    setCategoriesLoading(false);

    if (error) {
      setCategoryError("Failed to add category");
      console.error("Supabase add category error:", error);
      return;
    }

    await createAuditLog({
      action: "created",
      entity_type: "category",
      entity_id: data?.id ?? null,
      entity_label: categoryName,
      description: `Created category ${categoryName}`,
      new_values: { name: categoryName, parent_category_id: parentCategoryId },
    });
    setCategoryMessage("Category added successfully");
    setCategoryName("");
    setParentCategoryId(null);
    setCategoryOversellingPolicy("inherit");
    fetchCategories();
